INSERT INTO military_vehicles
  (`name`, `category`, `country`, `era`, `image_url`, `top_speed`, `range`, `crew`, `weight`, `armament`, `description`, `admin_note`)
VALUES
  ('M1A2 Abrams', 'Main Battle Tank', 'USA', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0b/M1A2_SEP_v3.jpg/960px-M1A2_SEP_v3.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '67 km/h', '426 km', '4', '62 tons', '120mm M256 smoothbore gun, 2x 7.62mm, 1x 12.7mm', 'The M1A2 Abrams is the main battle tank of the United States Army, featuring advanced composite armor, a 120mm smoothbore cannon, and a gas-turbine engine.', 'Export variant restrictions apply. Verify FMS documentation.'),
  ('Leopard 2A7', 'Main Battle Tank', 'Germany', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a7/Leopard_2_A7V_313_Bad_Frankenhausen_2024.JPG/960px-Leopard_2_A7V_313_Bad_Frankenhausen_2024.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '68 km/h', '450 km', '4', '67 tons', '120mm Rheinmetall L/55 smoothbore gun, 2x 7.62mm MG3', 'The Leopard 2A7 is a third-generation German main battle tank, widely regarded for its firepower, protection, and mobility across NATO forces.', ''),
  ('T-90M Proryv', 'Main Battle Tank', 'Russia', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d9/T-90M.jpg/960px-T-90M.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '60 km/h', '550 km', '3', '48 tons', '125mm 2A46M-5 smoothbore gun, Kord 12.7mm, PKTM 7.62mm', 'The T-90M is a modernized Russian main battle tank with the Relikt explosive reactive armor package and an upgraded fire-control system.', ''),
  ('M2A3 Bradley', 'Infantry Fighting Vehicle', 'USA', 'Cold War', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/91/US_M2A1_Bradley_deployed_to_Saudi_Arabia_during_Operation_Desert_Shield.jpg/960px-US_M2A1_Bradley_deployed_to_Saudi_Arabia_during_Operation_Desert_Shield.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '66 km/h', '400 km', '3 + 6 troops', '27 tons', '25mm M242 Bushmaster, TOW missile launcher, 7.62mm coax', 'The M2 Bradley is a tracked infantry fighting vehicle that transports a squad while providing fire support with its autocannon and anti-tank missiles.', ''),
  ('BMP-3', 'Infantry Fighting Vehicle', 'Russia', 'Cold War', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/04/Army2016demo-011.jpg/960px-Army2016demo-011.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '70 km/h', '600 km', '3 + 7 troops', '18.7 tons', '100mm 2A70 gun, 30mm 2A72 autocannon, 3x 7.62mm PKT', 'The BMP-3 is a Soviet-designed amphibious infantry fighting vehicle with a uniquely heavy mixed-caliber armament package for its class.', ''),
  ('M1126 Stryker', 'Armored Personnel Carrier', 'USA', 'Modern', 'https://upload.wikimedia.org/wikipedia/commons/5/51/Stryker_ICV_front_q.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled', '100 km/h', '500 km', '2 + 9 troops', '18 tons', '12.7mm M2 or 40mm Mk19 grenade launcher (RWS)', 'The Stryker is an eight-wheeled armored personnel carrier providing rapid, protected mobility for infantry squads on the modern battlefield.', ''),
  ('M109A7 Paladin', 'Self-Propelled Artillery', 'USA', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3a/Kings_of_battle_keep_the_fire%3B_1-9_FA_fires_its_last_rounds_140910-A-CW513-046.jpg/960px-Kings_of_battle_keep_the_fire%3B_1-9_FA_fires_its_last_rounds_140910-A-CW513-046.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '61 km/h', '300 km', '4', '36 tons', '155mm M284 howitzer, 12.7mm M2 machine gun', 'The M109A7 Paladin is a self-propelled 155mm howitzer providing indirect fire support with improved survivability and automated loading.', ''),
  ('Tiger I', 'Heavy Tank', 'Germany', 'WWII', 'https://upload.wikimedia.org/wikipedia/commons/b/ba/Bundesarchiv_Bild_101I-299-1805-16%2C_Nordfrankreich%2C_Panzer_VI_%28Tiger_I%29.2.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled', '45 km/h', '195 km', '5', '57 tons', '88mm KwK 36 L/56 gun, 2x 7.92mm MG 34', 'The Tiger I was a German heavy tank of World War II, renowned for its powerful 88mm gun and thick frontal armor that dominated early engagements.', 'Historical reference entry — not in active service.'),
  ('Challenger 2', 'Main Battle Tank', 'United Kingdom', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/30/Challenger_2_Main_Battle_Tank_patrolling_outside_Basra%2C_Iraq_MOD_45148325.jpg/960px-Challenger_2_Main_Battle_Tank_patrolling_outside_Basra%2C_Iraq_MOD_45148325.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '59 km/h', '550 km', '4', '62.5 tons', '120mm L30A1 rifled gun, 7.62mm L94A1 chain gun, 7.62mm L37A2 MG', 'The Challenger 2 is the British Army''s main battle tank, known for its Dorchester armour and its service in the Balkans and Iraq.', ''),
  ('Leclerc', 'Main Battle Tank', 'France', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fc/Leclerc-openphotonet_PICT6015.JPG/960px-Leclerc-openphotonet_PICT6015.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '71 km/h', '550 km', '3', '57 tons', '120mm CN120-26/52 smoothbore gun with autoloader, 12.7mm M2HB coax, 7.62mm MG', 'The Leclerc is France''s main battle tank, featuring an autoloader that allows a three-person crew and a high-performance hyperbar diesel engine.', ''),
  ('Merkava Mk 4', 'Main Battle Tank', 'Israel', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/43/Merkava-Mk4m-whiteback01.jpg/960px-Merkava-Mk4m-whiteback01.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '64 km/h', '500 km', '4', '65 tons', '120mm MG253 smoothbore gun, 60mm mortar, 3x 7.62mm MG', 'The Merkava Mk 4 places its engine at the front for extra crew protection and has a rear hatch that can carry infantry or casualties. It is fitted with the Trophy active protection system.', ''),
  ('K2 Black Panther', 'Main Battle Tank', 'South Korea', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/41/U.S.%2C_ROK_forces_forge_interoperability_with_combined_arms_exercise_-_8_of_8.jpg/960px-U.S.%2C_ROK_forces_forge_interoperability_with_combined_arms_exercise_-_8_of_8.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '70 km/h', '450 km', '3', '55 tons', '120mm CN08 L/55 smoothbore gun with autoloader, 12.7mm K6, 7.62mm coax', 'The K2 Black Panther is one of the most advanced tanks in service, with hydropneumatic suspension that lets it kneel and tilt to aim over terrain.', ''),
  ('Type 10', 'Main Battle Tank', 'Japan', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/76/Type10MBT.jpg/960px-Type10MBT.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '70 km/h', '440 km', '3', '44 tons', '120mm L/44 smoothbore gun with autoloader, 12.7mm M2, 7.62mm coax', 'The Type 10 is a lightweight Japanese main battle tank with modular ceramic armour and a C4I network system, designed for mobility on Japan''s roads and bridges.', ''),
  ('Type 99A', 'Main Battle Tank', 'China', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/77/ZTZ-99A_tank_front_20170902.jpg/960px-ZTZ-99A_tank_front_20170902.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '70 km/h', '450 km', '3', '55 tons', '125mm ZPT-98 smoothbore gun with autoloader, 12.7mm QJC-88, 7.62mm coax', 'The Type 99A is the most capable main battle tank of the Chinese People''s Liberation Army, fitted with composite and reactive armour and a laser warning system.', ''),
  ('T-14 Armata', 'Main Battle Tank', 'Russia', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9e/VDayRehearsal05052016-28.jpg/960px-VDayRehearsal05052016-28.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '80 km/h', '500 km', '3', '55 tons', '125mm 2A82-1M smoothbore gun, 12.7mm Kord RWS, 7.62mm PKTM', 'The T-14 Armata is a Russian tank with an unmanned turret; its crew of three sits in an armoured capsule in the hull. Only a small number have been produced.', ''),
  ('T-72B3', 'Main Battle Tank', 'Russia', 'Cold War', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Alabino05042017-40.jpg/960px-Alabino05042017-40.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '60 km/h', '460 km', '3', '46 tons', '125mm 2A46M-5 smoothbore gun, 12.7mm Kord, 7.62mm PKT', 'The T-72 is one of the most widely produced tanks in history. The B3 upgrade adds modern thermal sights and a better fire-control system to the 1970s Soviet design.', ''),
  ('T-80BV', 'Main Battle Tank', 'Soviet Union', 'Cold War', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/ff/T-80BVM.jpg/960px-T-80BVM.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '70 km/h', '335 km', '3', '42.5 tons', '125mm 2A46-2 smoothbore gun, 12.7mm NSVT, 7.62mm PKT', 'The T-80 was the first production tank to use a gas-turbine engine as its main powerplant, giving it high speed at the cost of heavy fuel consumption.', ''),
  ('T-55', 'Main Battle Tank', 'Soviet Union', 'Cold War', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/60/T-55_4.jpg/960px-T-55_4.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '50 km/h', '500 km', '4', '36 tons', '100mm D-10T2S rifled gun, 12.7mm DShK, 7.62mm SGMT', 'The T-54/T-55 series is the most-produced tank family in history, with tens of thousands built and service in more than 50 countries.', ''),
  ('M60A3 Patton', 'Main Battle Tank', 'USA', 'Cold War', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a7/M60_Patton_Tank_Fort_Lewis_Military_Museum.jpg/960px-M60_Patton_Tank_Fort_Lewis_Military_Museum.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '48 km/h', '480 km', '4', '52.6 tons', '105mm M68 rifled gun, 12.7mm M85, 7.62mm M240', 'The M60 was the US Army''s main battle tank through most of the Cold War; the A3 variant added a laser rangefinder and thermal sights.', ''),
  ('Leopard 1A5', 'Main Battle Tank', 'West Germany', 'Cold War', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f9/Leopard_1A5.jpg/960px-Leopard_1A5.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '65 km/h', '600 km', '4', '42.4 tons', '105mm L7A3 rifled gun, 2x 7.62mm MG3', 'The Leopard 1 put mobility ahead of armour and became one of the most successful Western tanks of the Cold War, exported across Europe and beyond.', ''),
  ('Chieftain Mk 10', 'Main Battle Tank', 'United Kingdom', 'Cold War', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ad/Chieftain_Tank_%289628802829%29.jpg/960px-Chieftain_Tank_%289628802829%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '48 km/h', '500 km', '4', '55 tons', '120mm L11A5 rifled gun, 12.7mm ranging MG, 2x 7.62mm MG', 'The Chieftain was the most heavily armed and armoured tank in NATO when it entered service in the 1960s, and it introduced a reclined driver position.', ''),
  ('Centurion', 'Main Battle Tank', 'United Kingdom', 'Cold War', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a1/Centurion_cfb_borden_1.JPG/960px-Centurion_cfb_borden_1.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '35 km/h', '190 km', '4', '51 tons', '105mm L7 rifled gun (later marks), 7.62mm coax', 'The Centurion was one of the most successful post-war tank designs, serving in conflicts from Korea to the Middle East for more than 50 years.', ''),
  ('Arjun Mk 1A', 'Main Battle Tank', 'India', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b7/Arjun_MK1A_field_trials.jpg/960px-Arjun_MK1A_field_trials.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '58 km/h', '450 km', '4', '68 tons', '120mm rifled gun, 12.7mm AA MG, 7.62mm coax', 'The Arjun is India''s domestically developed main battle tank; the Mk 1A adds dozens of upgrades to firepower, mobility, and protection.', ''),
  ('Altay', 'Main Battle Tank', 'Turkey', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/eb/Altay_Tank.jpg/960px-Altay_Tank.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '65 km/h', '450 km', '4', '65 tons', '120mm L/55 smoothbore gun, 12.7mm RWS, 7.62mm coax', 'The Altay is Turkey''s new-generation main battle tank, developed with South Korean assistance and based on K2 technology.', ''),
  ('C1 Ariete', 'Main Battle Tank', 'Italy', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/52/Italian_Army_-_4th_Tank_Regiment_-_Ariete_tanks_during_an_exercise_at_Capo_Teulada_October_2022.jpg/960px-Italian_Army_-_4th_Tank_Regiment_-_Ariete_tanks_during_an_exercise_at_Capo_Teulada_October_2022.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '65 km/h', '550 km', '4', '54 tons', '120mm OTO Melara smoothbore gun, 2x 7.62mm MG', 'The Ariete is the Italian Army''s main battle tank, built by the Iveco–OTO Melara consortium and in service since 1995.', ''),
  ('Stridsvagn 122', 'Main Battle Tank', 'Sweden', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f8/Strv122_3_cropped.jpg/960px-Strv122_3_cropped.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '68 km/h', '550 km', '4', '62 tons', '120mm L/44 smoothbore gun, 2x 7.62mm MG', 'The Stridsvagn 122 is a Swedish Leopard 2 variant with extra armour and a command-and-control system tailored to the Swedish Army.', ''),
  ('PT-91 Twardy', 'Main Battle Tank', 'Poland', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/51/PT91_MSPO15_DSC02773.JPG/960px-PT91_MSPO15_DSC02773.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '60 km/h', '650 km', '3', '45.3 tons', '125mm 2A46 smoothbore gun, 12.7mm NSVT, 7.62mm PKT', 'The PT-91 Twardy is a Polish development of the T-72M1, adding ERAWA explosive reactive armour and a modernised fire-control system.', ''),
  ('T-84 Oplot-M', 'Main Battle Tank', 'Ukraine', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cd/Strong_Europe_Tank_Challenge_2018_%2842054365704%29_%28cropped%29.jpg/960px-Strong_Europe_Tank_Challenge_2018_%2842054365704%29_%28cropped%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '70 km/h', '500 km', '3', '51 tons', '125mm KBA-3 smoothbore gun, 12.7mm KT-12.7, 7.62mm coax', 'The Oplot-M is Ukraine''s most advanced tank, developed from the T-80UD with a welded turret, Duplet reactive armour, and a diesel engine.', ''),
  ('Al-Khalid', 'Main Battle Tank', 'Pakistan', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2c/Al-Khalid_IDEAS_2012.jpg/960px-Al-Khalid_IDEAS_2012.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '70 km/h', '450 km', '3', '48 tons', '125mm smoothbore gun with autoloader, 12.7mm AA MG, 7.62mm coax', 'The Al-Khalid was jointly developed by Pakistan and China and serves as a mainstay of the Pakistan Army''s armoured corps.', ''),
  ('M4A3E8 Sherman', 'Medium Tank', 'USA', 'WWII', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/53/M4_Sherman_tank_-_Flickr_-_Joost_J._Bakker_IJmuiden.jpg/960px-M4_Sherman_tank_-_Flickr_-_Joost_J._Bakker_IJmuiden.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '48 km/h', '160 km', '5', '33.7 tons', '76mm M1 gun, 12.7mm M2, 2x 7.62mm M1919', 'The M4 Sherman was the most widely used Allied tank of WWII. The "Easy Eight" variant added a longer 76mm gun and horizontal volute spring suspension.', ''),
  ('T-34-85', 'Medium Tank', 'Soviet Union', 'WWII', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dd/Tank_T-34.JPG/960px-Tank_T-34.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '55 km/h', '300 km', '5', '32 tons', '85mm ZiS-S-53 gun, 2x 7.62mm DT', 'The T-34 combined sloped armour, a powerful gun, and ease of production. The T-34-85 up-gunned version became the backbone of Soviet armoured forces in 1944–45.', ''),
  ('Panther Ausf. G', 'Medium Tank', 'Germany', 'WWII', 'https://upload.wikimedia.org/wikipedia/commons/6/61/Bundesarchiv_Bild_183-H26258%2C_Panzer_V_%22Panther%22.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled', '46 km/h', '200 km', '5', '44.8 tons', '75mm KwK 42 L/70 gun, 2x 7.92mm MG 34', 'The Panther was Germany''s answer to the T-34, pairing a high-velocity 75mm gun with thick sloped frontal armour.', ''),
  ('Panzer IV Ausf. H', 'Medium Tank', 'Germany', 'WWII', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e1/Panzermuseum_Munster_2010_0128_b.jpg/960px-Panzermuseum_Munster_2010_0128_b.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '38 km/h', '200 km', '5', '25 tons', '75mm KwK 40 L/48 gun, 2x 7.92mm MG 34', 'The Panzer IV was the only German tank to stay in production for the whole war, adapting from infantry support to a capable anti-tank role.', ''),
  ('Cromwell', 'Medium Tank', 'United Kingdom', 'WWII', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a6/Cromwell_%28A27M%29_front-right_2017_Bovington.jpg/960px-Cromwell_%28A27M%29_front-right_2017_Bovington.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '64 km/h', '270 km', '5', '27.9 tons', '75mm OQF gun, 2x 7.92mm Besa MG', 'The Cromwell was one of the fastest tanks of WWII thanks to its Rolls-Royce Meteor engine, derived from the Merlin aero engine.', ''),
  ('Type 97 Chi-Ha', 'Medium Tank', 'Japan', 'WWII', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e8/Type_97_Chi-Ha_in_the_Great_Patriotic_War_Museum_5-jun-2014.jpg/960px-Type_97_Chi-Ha_in_the_Great_Patriotic_War_Museum_5-jun-2014.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '38 km/h', '210 km', '4', '15 tons', '57mm Type 97 gun, 2x 7.7mm Type 97 MG', 'The Type 97 Chi-Ha was the most widely produced Japanese medium tank of WWII, used across China, the Pacific, and Southeast Asia.', ''),
  ('Tiger II', 'Heavy Tank', 'Germany', 'WWII', 'https://upload.wikimedia.org/wikipedia/commons/e/ef/Bundesarchiv_Bild_101I-721-0398-21A%2C_Frankreich%2C_Panzer_VI_%28Tiger_II%2C_K%C3%B6nigstiger%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled', '41.5 km/h', '170 km', '5', '69.8 tons', '88mm KwK 43 L/71 gun, 2x 7.92mm MG 34', 'The Tiger II ("King Tiger") combined the long 88mm gun with heavily sloped armour, but its weight made it unreliable and fuel-hungry.', ''),
  ('IS-2', 'Heavy Tank', 'Soviet Union', 'WWII', 'https://upload.wikimedia.org/wikipedia/commons/f/f7/%D0%9C%D0%B5%D0%BC%D0%BE%D1%80%D1%96%D0%B0%D0%BB%D1%8C%D0%BD%D0%B8%D0%B9_%D0%BA%D0%BE%D0%BC%D0%BF%D0%BB%D0%B5%D0%BA%D1%81_%C2%AB%D0%A1%D0%B0%D0%BF%D1%83%D0%BD-%D0%B3%D0%BE%D1%80%D0%B0%C2%BB2.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled', '37 km/h', '240 km', '4', '46 tons', '122mm D-25T gun, 12.7mm DShK, 3x 7.62mm DT', 'The IS-2 was a Soviet breakthrough tank whose 122mm gun was designed to knock out fortifications and German heavy tanks alike.', ''),
  ('KV-1', 'Heavy Tank', 'Soviet Union', 'WWII', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8c/%D0%9A%D0%92-1_%D1%83_%D0%B4%D0%B8%D0%BE%D1%80%D0%B0%D0%BC%D1%8B_%C2%AB%D0%9F%D1%80%D0%BE%D1%80%D1%8B%D0%B2_%D0%B1%D0%BB%D0%BE%D0%BA%D0%B0%D0%B4%D1%8B_%D0%9B%D0%B5%D0%BD%D0%B8%D0%BD%D0%B3%D1%80%D0%B0%D0%B4%D0%B0%C2%BB._%D0%92%D0%B8%D0%B4_%D1%81%D0%BF%D0%B5%D1%80%D0%B5%D0%B4%D0%B8-%D1%81%D0%BF%D1%80%D0%B0%D0%B2%D0%B0.JPG/960px-%D0%9A%D0%92-1_%D1%83_%D0%B4%D0%B8%D0%BE%D1%80%D0%B0%D0%BC%D1%8B_%C2%AB%D0%9F%D1%80%D0%BE%D1%80%D1%8B%D0%B2_%D0%B1%D0%BB%D0%BE%D0%BA%D0%B0%D0%B4%D1%8B_%D0%9B%D0%B5%D0%BD%D0%B8%D0%BD%D0%B3%D1%80%D0%B0%D0%B4%D0%B0%C2%BB._%D0%92%D0%B8%D0%B4_%D1%81%D0%BF%D0%B5%D1%80%D0%B5%D0%B4%D0%B8-%D1%81%D0%BF%D1%80%D0%B0%D0%B2%D0%B0.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '35 km/h', '250 km', '5', '45 tons', '76.2mm ZiS-5 gun, 3x 7.62mm DT', 'The KV-1 was nearly immune to German anti-tank guns in 1941, and a single KV could hold up entire columns during the early months of Operation Barbarossa.', ''),
  ('Churchill Mk VII', 'Heavy Tank', 'United Kingdom', 'WWII', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/42/Tanks_and_Afvs_of_the_British_Army_1939-45_KID1265.jpg/960px-Tanks_and_Afvs_of_the_British_Army_1939-45_KID1265.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '21 km/h', '140 km', '5', '41 tons', '75mm OQF gun, 2x 7.92mm Besa MG', 'The Churchill was a heavily armoured British infantry tank that could climb steep terrain, and it formed the basis of many specialist engineering vehicles.', ''),
  ('M26 Pershing', 'Heavy Tank', 'USA', 'WWII', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4d/Flickr_-_davehighbury_-_Bovington_Tank_Museum_246_M26.jpg/960px-Flickr_-_davehighbury_-_Bovington_Tank_Museum_246_M26.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '40 km/h', '160 km', '5', '41.9 tons', '90mm M3 gun, 12.7mm M2, 2x 7.62mm M1919', 'The M26 Pershing arrived in the last months of WWII and became the basis for the US Patton tank series.', ''),
  ('M24 Chaffee', 'Light Tank', 'USA', 'WWII', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7f/M24_Chaffee_tankfest_2023.JPG/960px-M24_Chaffee_tankfest_2023.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '56 km/h', '160 km', '5', '18.4 tons', '75mm M6 gun, 12.7mm M2, 2x 7.62mm M1919', 'The M24 Chaffee replaced the M3/M5 Stuart, adding a 75mm gun while keeping the speed a reconnaissance tank needs.', ''),
  ('M3 Stuart', 'Light Tank', 'USA', 'WWII', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/53/Stuart_tankfest_2023.JPG/960px-Stuart_tankfest_2023.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '58 km/h', '120 km', '4', '14.7 tons', '37mm M6 gun, 3x 7.62mm M1919', 'The M3 Stuart was a fast, reliable light tank supplied to Allied forces around the world. British crews nicknamed it the "Honey".', ''),
  ('PT-76', 'Light Tank', 'Soviet Union', 'Cold War', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/28/Verkhnyaya_Pyshma_Tank_Museum_2012_0181.jpg/960px-Verkhnyaya_Pyshma_Tank_Museum_2012_0181.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '44 km/h', '370 km', '3', '14.6 tons', '76.2mm D-56T gun, 7.62mm SGMT', 'The PT-76 is an amphibious light tank that swims with water jets. It saw action from Vietnam to the Indo-Pakistani wars.', ''),
  ('M551 Sheridan', 'Light Tank', 'USA', 'Cold War', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0a/Yuma_Proving_Ground%2C_Arizona_%2842188342504%29.jpg/960px-Yuma_Proving_Ground%2C_Arizona_%2842188342504%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '70 km/h', '560 km', '4', '15.2 tons', '152mm M81 gun/launcher (MGM-51 Shillelagh), 12.7mm M2, 7.62mm coax', 'The M551 Sheridan was an air-droppable light tank whose 152mm gun could fire both conventional shells and guided missiles.', ''),
  ('FV101 Scorpion', 'Light Tank', 'United Kingdom', 'Cold War', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2f/Scorpion_CRVT_%284119399295%29.jpg/960px-Scorpion_CRVT_%284119399295%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '72 km/h', '756 km', '3', '8 tons', '76mm L23A1 gun, 7.62mm L43A1 coax', 'The Scorpion holds the record as the fastest production tank. It was light enough to be airlifted and used aluminium armour.', ''),
  ('ZTQ-15', 'Light Tank', 'China', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/75/Type_15_tank_20221020.jpg/960px-Type_15_tank_20221020.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '70 km/h', '450 km', '3', '36 tons', '105mm rifled gun, 12.7mm HMG, 7.62mm coax', 'The ZTQ-15 (Type 15) light tank was designed for high-altitude and rugged terrain such as the Tibetan Plateau, where heavy tanks struggle.', ''),
  ('M10 Booker', 'Light Tank', 'USA', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fa/M10_Booker_at_its_unveiling_June_2023_-_7.jpg/960px-M10_Booker_at_its_unveiling_June_2023_-_7.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '64 km/h', '', '4', '42 tons', '105mm M35 rifled gun, 12.7mm M2, 7.62mm coax', 'The M10 Booker was a US Army infantry-support vehicle developed under the Mobile Protected Firepower program. The Army cancelled it in 2025.', ''),
  ('Jagdpanther', 'Tank Destroyer', 'Germany', 'WWII', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/41/Jagdpanzer_V_Jagdpanther_1.jpg/960px-Jagdpanzer_V_Jagdpanther_1.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '46 km/h', '160 km', '5', '45.5 tons', '88mm Pak 43/3 L/71 gun, 7.92mm MG 34', 'The Jagdpanther mounted the Tiger II''s 88mm gun on a Panther chassis and is often regarded as one of the best tank destroyers of the war.', ''),
  ('StuG III Ausf. G', 'Tank Destroyer', 'Germany', 'WWII', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/18/SNC15697_%285853637442%29_b.jpg/960px-SNC15697_%285853637442%29_b.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '40 km/h', '155 km', '4', '23.9 tons', '75mm StuK 40 L/48 gun, 7.92mm MG 34', 'The StuG III was Germany''s most-produced fully tracked armoured fighting vehicle of WWII. Its low profile made it an effective assault gun and tank hunter.', ''),
  ('M18 Hellcat', 'Tank Destroyer', 'USA', 'WWII', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/43/M18_hellcat_side.jpg/960px-M18_hellcat_side.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '80 km/h', '169 km', '5', '17.7 tons', '76mm M1A1 gun, 12.7mm M2', 'The M18 Hellcat was the fastest tracked armoured vehicle of WWII, sacrificing armour for speed and ambush tactics.', ''),
  ('SU-100', 'Tank Destroyer', 'Soviet Union', 'WWII', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5a/Su-100_-_TankBiathlon2013-07.jpg/960px-Su-100_-_TankBiathlon2013-07.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '48 km/h', '310 km', '4', '31.6 tons', '100mm D-10S gun', 'The SU-100 put a powerful 100mm gun on the T-34 chassis and remained in service with some armies decades after WWII.', ''),
  ('B1 Centauro', 'Tank Destroyer', 'Italy', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/70/Centauro01.JPEG/960px-Centauro01.JPEG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '108 km/h', '800 km', '4', '25 tons', '105mm L/52 rifled gun, 2x 7.62mm MG', 'The Centauro is an eight-wheeled tank destroyer that pioneered the concept of a wheeled vehicle carrying a tank-calibre gun.', ''),
  ('2S25 Sprut-SD', 'Tank Destroyer', 'Russia', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3b/2008_Moscow_Victory_Day_Parade_%2859-18%29.jpg/960px-2008_Moscow_Victory_Day_Parade_%2859-18%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '70 km/h', '500 km', '3', '18 tons', '125mm 2A75 smoothbore gun, 7.62mm PKT', 'The Sprut-SD is an amphibious, air-droppable tank destroyer for Russian airborne forces, armed with a full-size 125mm tank gun.', ''),
  ('CV90', 'Infantry Fighting Vehicle', 'Sweden', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/30/Stridsfordon_90_Revinge_2012-2.jpg/960px-Stridsfordon_90_Revinge_2012-2.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '70 km/h', '600 km', '3 + 8 troops', '35 tons', '40mm Bofors L/70 autocannon (CV9040), 7.62mm coax', 'The CV90 family was designed for Nordic winters and is now operated by many European armies in a wide range of variants.', ''),
  ('Puma', 'Infantry Fighting Vehicle', 'Germany', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5d/Puma%2C_first_series.jpg/960px-Puma%2C_first_series.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '70 km/h', '600 km', '3 + 6 troops', '43 tons', '30mm MK30-2/ABM autocannon, 5.56mm MG4, Spike-LR ATGM', 'The Puma is one of the most heavily protected infantry fighting vehicles in the world, with modular armour packages and a remote-controlled turret.', ''),
  ('Marder 1A3', 'Infantry Fighting Vehicle', 'West Germany', 'Cold War', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1a/IL%C3%9C_der_Bundeswehr_am_24.09.2012_--_Marder_AT_%28cropped%29.jpg/960px-IL%C3%9C_der_Bundeswehr_am_24.09.2012_--_Marder_AT_%28cropped%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '65 km/h', '520 km', '3 + 6 troops', '35 tons', '20mm Rh 202 autocannon, 7.62mm MG3, MILAN ATGM', 'The Marder was the first infantry fighting vehicle fielded by a NATO army and served the Bundeswehr for five decades.', ''),
  ('FV510 Warrior', 'Infantry Fighting Vehicle', 'United Kingdom', 'Cold War', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fd/ARMOURED_VEHICLE_FLEET_SUPPORT_CONTRACT_ANNOUNCED_%2845149221%29.jpg/960px-ARMOURED_VEHICLE_FLEET_SUPPORT_CONTRACT_ANNOUNCED_%2845149221%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '75 km/h', '660 km', '3 + 7 troops', '25.4 tons', '30mm L21A1 RARDEN cannon, 7.62mm L94A1 chain gun', 'The Warrior has been the British Army''s tracked infantry fighting vehicle since 1988 and saw extensive service in the Gulf, the Balkans, and Iraq.', ''),
  ('BMP-1', 'Infantry Fighting Vehicle', 'Soviet Union', 'Cold War', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cf/BWP-1_Baltops_2016_0283.jpg/960px-BWP-1_Baltops_2016_0283.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '65 km/h', '600 km', '3 + 8 troops', '13.2 tons', '73mm 2A28 Grom gun, 9M14 Malyutka ATGM, 7.62mm PKT', 'The BMP-1 was the world''s first mass-produced infantry fighting vehicle. It let troops fight from inside the vehicle under armour.', ''),
  ('BMP-2', 'Infantry Fighting Vehicle', 'Soviet Union', 'Cold War', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/Army2016demo-007.jpg/960px-Army2016demo-007.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '65 km/h', '600 km', '3 + 7 troops', '14 tons', '30mm 2A42 autocannon, 9M113 Konkurs ATGM, 7.62mm PKT', 'The BMP-2 replaced its predecessor''s low-pressure gun with a rapid-fire 30mm autocannon that can engage helicopters and light vehicles.', ''),
  ('VBCI', 'Infantry Fighting Vehicle', 'France', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6f/VBCI%2C_nouvelles_couleurs_Arm%C3%A9e_de_Terre_%2814_juillet_2021%29_%284%29.jpg/960px-VBCI%2C_nouvelles_couleurs_Arm%C3%A9e_de_Terre_%2814_juillet_2021%29_%284%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '100 km/h', '750 km', '2 + 9 troops', '28 tons', '25mm M811 autocannon, 7.62mm coax', 'The VBCI is a French eight-wheeled infantry fighting vehicle built for strategic mobility, and it has been deployed to Mali and Lebanon.', ''),
  ('K21', 'Infantry Fighting Vehicle', 'South Korea', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c9/2014.4.1_%EC%9C%A1%EA%B5%B0_%EC%88%98%EB%8F%84%EA%B8%B0%EA%B3%84%ED%99%94%EB%B3%B4%EB%B3%91%EC%82%AC%EB%8B%A8_K-21_%EC%9E%A5%EA%B0%91%EC%B0%A8_%EC%82%AC%EA%B2%A9%EC%A7%91%EC%A4%91%ED%9B%88%EB%A0%A8_Republic_of_Korea_Army_%2813592630584%29.jpg/960px-2014.4.1_%EC%9C%A1%EA%B5%B0_%EC%88%98%EB%8F%84%EA%B8%B0%EA%B3%84%ED%99%94%EB%B3%B4%EB%B3%91%EC%82%AC%EB%8B%A8_K-21_%EC%9E%A5%EA%B0%91%EC%B0%A8_%EC%82%AC%EA%B2%A9%EC%A7%91%EC%A4%91%ED%9B%88%EB%A0%A8_Republic_of_Korea_Army_%2813592630584%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', '70 km/h', '500 km', '3 + 9 troops', '25 tons', '40mm K40 autocannon, 7.62mm coax, Hyungung ATGM', 'The K21 uses a composite hull to stay light enough to swim while carrying a powerful 40mm gun.', ''),
  ('ZBD-04A', 'Infantry Fighting Vehicle', 'China', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5c/ZBD-04A_IFV_20170716.jpg/960px-ZBD-04A_IFV_20170716.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '65 km/h', '500 km', '3 + 7 troops', '24 tons', '100mm gun/launcher, 30mm autocannon, 7.62mm coax', 'The ZBD-04 is a Chinese amphibious infantry fighting vehicle whose turret layout is inspired by the BMP-3.', ''),
  ('BMD-4M', 'Infantry Fighting Vehicle', 'Russia', 'Modern', 'https://upload.wikimedia.org/wikipedia/commons/4/49/2008_Moscow_Victory_Day_Parade_-_BMD-4.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled', '70 km/h', '500 km', '3 + 5 troops', '13.6 tons', '100mm 2A70 gun, 30mm 2A72 autocannon, 7.62mm PKT', 'The BMD-4M is an air-droppable infantry fighting vehicle for Russian airborne troops, sharing the BMP-3''s heavy turret.', ''),
  ('Lynx KF41', 'Infantry Fighting Vehicle', 'Germany', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e1/Hungarian_Lynx_KF-41.jpg/960px-Hungarian_Lynx_KF-41.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '70 km/h', '500 km', '3 + 8 troops', '44 tons', '30mm or 35mm Wotan autocannon, 7.62mm coax, Spike-LR ATGM', 'The Rheinmetall Lynx is a modular infantry fighting vehicle chosen by Hungary and Italy, built to be reconfigured for different missions.', ''),
  ('M113', 'Armored Personnel Carrier', 'USA', 'Cold War', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/aa/Allied_Spirit_I_150126-A-LO967-001.jpg/960px-Allied_Spirit_I_150126-A-LO967-001.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '67 km/h', '480 km', '2 + 11 troops', '12.3 tons', '12.7mm M2 Browning', 'The M113 is the most widely used armoured fighting vehicle family ever, with more than 80,000 built in dozens of variants. The Philippine Army also operates it.', ''),
  ('BTR-80', 'Armored Personnel Carrier', 'Soviet Union', 'Cold War', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7b/BTR-80_swimming.jpg/960px-BTR-80_swimming.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', '80 km/h', '600 km', '3 + 7 troops', '13.6 tons', '14.5mm KPVT, 7.62mm PKT', 'The BTR-80 is an eight-wheeled amphibious armoured personnel carrier that serves widely across the former Soviet Union and beyond.', ''),
  ('BTR-82A', 'Armored Personnel Carrier', 'Russia', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3f/2011_Moscow_Victory_Day_Parade_%28360-06%29_%28cropped%29.jpg/960px-2011_Moscow_Victory_Day_Parade_%28360-06%29_%28cropped%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '80 km/h', '600 km', '3 + 7 troops', '15.4 tons', '30mm 2A72 autocannon, 7.62mm PKTM', 'The BTR-82A modernises the BTR-80 with a 30mm autocannon, spall liners, and improved night sights.', ''),
  ('Boxer', 'Armored Personnel Carrier', 'Germany', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c9/DSCN7330-crop_-_Copy.jpg/960px-DSCN7330-crop_-_Copy.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '103 km/h', '1,050 km', '3 + 8 troops', '36.5 tons', '12.7mm HMG or 40mm GMW grenade launcher (RWS)', 'The Boxer uses swappable mission modules on a common 8x8 drive chassis, so one platform can serve as a troop carrier, ambulance, or command post.', ''),
  ('Patria AMV', 'Armored Personnel Carrier', 'Finland', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/91/Pansarterr%C3%A4ngbil_360_Revinge_2015-7.jpg/960px-Pansarterr%C3%A4ngbil_360_Revinge_2015-7.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '100 km/h', '800 km', '2 + 10 troops', '26 tons', '12.7mm RWS or 30mm turret', 'The Patria AMV is a modular Finnish 8x8 vehicle known for protection and off-road mobility, operated by more than ten countries.', ''),
  ('Namer', 'Armored Personnel Carrier', 'Israel', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1f/Flickr_-_Israel_Defense_Forces_-_13th_Battalion_of_the_Golani_Brigade_Holds_Drill_at_Golan_Heights_%288%29.jpg/960px-Flickr_-_Israel_Defense_Forces_-_13th_Battalion_of_the_Golani_Brigade_Holds_Drill_at_Golan_Heights_%288%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '60 km/h', '500 km', '3 + 9 troops', '60 tons', '12.7mm M2 or 30mm RWS, 7.62mm MG', 'The Namer is built on a Merkava tank chassis, which makes it one of the most heavily armoured troop carriers in the world.', ''),
  ('FV432', 'Armored Personnel Carrier', 'United Kingdom', 'Cold War', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bc/FV_432_APC_of_the_7th_Brigade_Royal_Scots.JPEG/960px-FV_432_APC_of_the_7th_Brigade_Royal_Scots.JPEG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '52 km/h', '580 km', '2 + 10 troops', '15.3 tons', '7.62mm L7 GPMG', 'The FV432 has carried British infantry since the 1960s and remains in use as a mortar carrier, ambulance, and command vehicle.', ''),
  ('TPz Fuchs', 'Armored Personnel Carrier', 'West Germany', 'Cold War', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/91/Transportpanzer_Fuchs_%28TPz_Fuchs%29_der_Bundeswehr_%2810579660405%29.jpg/960px-Transportpanzer_Fuchs_%28TPz_Fuchs%29_der_Bundeswehr_%2810579660405%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '105 km/h', '800 km', '2 + 10 troops', '17 tons', '7.62mm MG3', 'The Fuchs is an amphibious 6x6 transport best known in NBC reconnaissance roles, detecting nuclear, biological, and chemical hazards.', ''),
  ('VAB', 'Armored Personnel Carrier', 'France', 'Cold War', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6c/Fin_de_d%C3%A9fil%C3%A9_14_juillet_2022%2C_Paris_Porte_d%27Orl%C3%A9ans_%281%29_04.jpg/960px-Fin_de_d%C3%A9fil%C3%A9_14_juillet_2022%2C_Paris_Porte_d%27Orl%C3%A9ans_%281%29_04.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '92 km/h', '1,000 km', '2 + 10 troops', '13.8 tons', '12.7mm M2 or 7.62mm MG', 'The VAB (Véhicule de l''Avant Blindé) was the French Army''s standard wheeled troop carrier for four decades.', ''),
  ('Sd.Kfz. 251', 'Armored Personnel Carrier', 'Germany', 'WWII', 'https://upload.wikimedia.org/wikipedia/commons/4/4f/Bundesarchiv_Bild_101I-801-0664-37%2C_Berlin%2C_Unter_den_Linden%2C_Sch%C3%BCtzenpanzer.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled', '52.5 km/h', '300 km', '2 + 10 troops', '9 tons', '2x 7.92mm MG 34/42', 'The Sd.Kfz. 251 half-track carried German panzergrenadiers so they could keep pace with the tanks, and it was built in more than 20 variants.', ''),
  ('M3 Half-track', 'Armored Personnel Carrier', 'USA', 'WWII', 'https://upload.wikimedia.org/wikipedia/commons/a/ad/Halftrack-fort-knox-1.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled', '72 km/h', '320 km', '3 + 10 troops', '9.1 tons', '12.7mm M2, 7.62mm M1919', 'The M3 Half-track was the main American armoured troop carrier of WWII and was supplied in large numbers to Allied forces.', ''),
  ('Universal Carrier', 'Armored Personnel Carrier', 'United Kingdom', 'WWII', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4f/Universal_carrier_%28mortar_carrier%29_9-08-2008_14-53-48_%282%29.JPG/960px-Universal_carrier_%28mortar_carrier%29_9-08-2008_14-53-48_%282%29.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '48 km/h', '250 km', '2–5', '3.75 tons', '.303 Bren LMG or Boys anti-tank rifle', 'The Universal Carrier (Bren Carrier) is the most-produced armoured fighting vehicle in history, with around 113,000 built.', ''),
  ('MaxxPro MRAP', 'Armored Personnel Carrier', 'USA', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/65/Navistar_MaxxPro.JPG/960px-Navistar_MaxxPro.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '105 km/h', '600 km', '2 + 6 troops', '14 tons', '12.7mm M2 or 40mm Mk19 (CROWS)', 'The MaxxPro is a mine-resistant ambush-protected vehicle with a V-shaped hull that deflects blasts from roadside bombs.', ''),
  ('Bushmaster PMV', 'Armored Personnel Carrier', 'Australia', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4e/Dutch_Bushmaster_with_remote_turret_2008.jpg/960px-Dutch_Bushmaster_with_remote_turret_2008.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '100 km/h', '800 km', '1 + 9 troops', '15 tons', '7.62mm or 12.7mm MG', 'The Bushmaster is an Australian protected mobility vehicle credited with saving many lives in Afghanistan, and it has been exported to several armies.', ''),
  ('PzH 2000', 'Self-Propelled Artillery', 'Germany', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e3/Lithuanian_PzH_2000_%282%29.jpg/960px-Lithuanian_PzH_2000_%282%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '60 km/h', '420 km', '5', '55.8 tons', '155mm L/52 howitzer, 7.62mm MG3', 'The Panzerhaubitze 2000 can fire three rounds in under ten seconds and put several shells on one target at the same moment (MRSI).', ''),
  ('K9 Thunder', 'Self-Propelled Artillery', 'South Korea', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ed/2011.2.17_%EC%9C%A1%EA%B5%B06%ED%8F%AC%EB%B3%91%EC%97%AC%EB%8B%A8_k-9%2Ck-55_%EC%9E%90%EC%A3%BC%ED%8F%AC%EC%82%AC%EA%B2%A9_%287633864346%29.jpg/960px-2011.2.17_%EC%9C%A1%EA%B5%B06%ED%8F%AC%EB%B3%91%EC%97%AC%EB%8B%A8_k-9%2Ck-55_%EC%9E%90%EC%A3%BC%ED%8F%AC%EC%82%AC%EA%B2%A9_%287633864346%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '67 km/h', '360 km', '5', '47 tons', '155mm L/52 howitzer, 12.7mm K6', 'The K9 Thunder is the world''s best-selling self-propelled howitzer, operated by more than ten countries.', ''),
  ('CAESAR', 'Self-Propelled Artillery', 'France', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/74/French_Caesar_self-propelled_howitzer_in_Iraq.jpg/960px-French_Caesar_self-propelled_howitzer_in_Iraq.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '100 km/h', '600 km', '5', '17.7 tons', '155mm L/52 truck-mounted howitzer', 'CAESAR mounts a 155mm howitzer on a 6x6 truck, so it can fire and move away within minutes and can be airlifted by a C-130.', ''),
  ('2S19 Msta-S', 'Self-Propelled Artillery', 'Soviet Union', 'Cold War', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/00/AlabinoTraining0904-34.jpg/960px-AlabinoTraining0904-34.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '60 km/h', '500 km', '5', '42 tons', '152mm 2A64 howitzer, 12.7mm NSVT', 'The 2S19 Msta-S is the main heavy self-propelled howitzer of the Russian Army, built on a hull that combines T-72 and T-80 components.', ''),
  ('2S3 Akatsiya', 'Self-Propelled Artillery', 'Soviet Union', 'Cold War', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ac/2S3_Akatsiya_3261.jpg/960px-2S3_Akatsiya_3261.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '60 km/h', '500 km', '4', '27.5 tons', '152mm 2A33 howitzer, 7.62mm PKT', 'The 2S3 Akatsiya was the Soviet answer to the M109 and remains in service across many former Warsaw Pact armies.', ''),
  ('AS-90', 'Self-Propelled Artillery', 'United Kingdom', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/55/AS90_%2852931434897%29.jpg/960px-AS90_%2852931434897%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '55 km/h', '370 km', '5', '45 tons', '155mm L/39 howitzer, 12.7mm HMG', 'The AS-90 was the British Army''s standard self-propelled gun from 1993 until it began being replaced, with many units donated to Ukraine.', ''),
  ('Archer', 'Self-Propelled Artillery', 'Sweden', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/21/Archerside_commons.jpg/960px-Archerside_commons.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '70 km/h', '500 km', '4', '33.5 tons', '155mm L/52 FH77BW howitzer, 12.7mm RWS', 'Archer is a fully automated wheeled howitzer that can fire its first round within 30 seconds of stopping and be moving again moments later.', ''),
  ('M7 Priest', 'Self-Propelled Artillery', 'USA', 'WWII', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/25/M7_Priest_at_APG.jpg/960px-M7_Priest_at_APG.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '38 km/h', '190 km', '7', '22.9 tons', '105mm M2A1 howitzer, 12.7mm M2', 'The M7 Priest got its name from its pulpit-like machine-gun ring and provided mobile artillery support to Allied armoured divisions.', ''),
  ('Wespe', 'Self-Propelled Artillery', 'Germany', 'WWII', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a9/SdKfz124.jpg/960px-SdKfz124.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '40 km/h', '220 km', '5', '11 tons', '105mm leFH 18/2 howitzer', 'The Wespe mounted a 105mm howitzer on an obsolete Panzer II chassis, giving panzer divisions mobile light artillery.', ''),
  ('M142 HIMARS', 'Rocket Artillery', 'USA', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/83/HIMARS_-_missile_launched.jpg/960px-HIMARS_-_missile_launched.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '85 km/h', '480 km', '3', '16.25 tons', '6x GMLRS guided rockets or 1x ATACMS missile', 'HIMARS is a wheeled rocket launcher that fires precision-guided rockets and relocates within minutes, making it hard to counter.', ''),
  ('M270 MLRS', 'Rocket Artillery', 'USA', 'Cold War', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/42/M270A1_Multiple_Launch_Rocket_System_South_Dakota_ANG.jpg/960px-M270A1_Multiple_Launch_Rocket_System_South_Dakota_ANG.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '64 km/h', '480 km', '3', '24.9 tons', '12x 227mm rockets or 2x ATACMS missiles', 'The M270 is a tracked multiple rocket launcher that can saturate a large area or fire precision rockets, operated by many NATO armies.', ''),
  ('BM-21 Grad', 'Rocket Artillery', 'Soviet Union', 'Cold War', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d8/Russian_BM-21_Grad_in_Saint_Petersburg.JPG/960px-Russian_BM-21_Grad_in_Saint_Petersburg.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '75 km/h', '750 km', '3', '13.7 tons', '40x 122mm rockets', 'The BM-21 Grad is the world''s most widespread multiple rocket launcher; it can fire all 40 rockets in about 20 seconds.', ''),
  ('BM-13 Katyusha', 'Rocket Artillery', 'Soviet Union', 'WWII', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ab/Katyusha_Rocket_Launcher_-_Artillery_Museum_-_St._Petersburg_-_Russia.jpg/960px-Katyusha_Rocket_Launcher_-_Artillery_Museum_-_St._Petersburg_-_Russia.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '', '', '5–7', '6.2 tons', '16x 132mm M-13 rockets', 'The Katyusha rocket launcher was feared for its sudden, howling salvos. German troops nicknamed it "Stalin''s organ".', ''),
  ('LAV-25', 'Reconnaissance', 'USA', 'Cold War', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/07/LAV-25A2.jpg/960px-LAV-25A2.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '100 km/h', '660 km', '3 + 6 scouts', '12.8 tons', '25mm M242 Bushmaster, 2x 7.62mm M240', 'The LAV-25 is the US Marine Corps'' amphibious light armoured reconnaissance vehicle, prized for speed and range.', ''),
  ('FV107 Scimitar', 'Reconnaissance', 'United Kingdom', 'Cold War', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4e/Scimitar_Light_Tank_MOD_45149231.jpg/960px-Scimitar_Light_Tank_MOD_45149231.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '80 km/h', '450 km', '3', '7.8 tons', '30mm L21 RARDEN cannon, 7.62mm L37A1', 'The Scimitar is a tracked reconnaissance vehicle from the CVR(T) family, used by British reconnaissance units for decades.', ''),
  ('Fennek', 'Reconnaissance', 'Germany', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/52/Fennek-highres.jpg/960px-Fennek-highres.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '115 km/h', '1,000 km', '3', '10 tons', '7.62mm MG3, 12.7mm HMG or 40mm GMW', 'The Fennek is a low-profile scout car with a mast-mounted sensor suite that can observe targets from long range while staying hidden.', ''),
  ('BRDM-2', 'Reconnaissance', 'Soviet Union', 'Cold War', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/ff/BRDM-2_%281964%29_owned_by_James_Stewart_pic1.JPG/960px-BRDM-2_%281964%29_owned_by_James_Stewart_pic1.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '95 km/h', '750 km', '4', '7 tons', '14.5mm KPVT, 7.62mm PKT', 'The BRDM-2 is an amphibious scout car with retractable belly wheels for crossing trenches, and it has been exported to dozens of countries.', ''),
  ('AMX-10 RC', 'Reconnaissance', 'France', 'Cold War', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4d/AMX-10_RC%2C_nouvelles_couleurs_Arm%C3%A9e_de_terre_%2814_juillet_2021%29_%282%29.jpg/960px-AMX-10_RC%2C_nouvelles_couleurs_Arm%C3%A9e_de_terre_%2814_juillet_2021%29_%282%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '85 km/h', '800 km', '4', '15.9 tons', '105mm F2 gun, 7.62mm coax', 'The AMX-10 RC is a six-wheeled armoured car with tank-like firepower, used for reconnaissance and fire support.', ''),
  ('EBRC Jaguar', 'Reconnaissance', 'France', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9b/E20iPMrXMAUFTsh.jpg/960px-E20iPMrXMAUFTsh.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '90 km/h', '800 km', '3', '25 tons', '40mm CTA40 cannon, 7.62mm RWS, 2x Akeron MP missiles', 'The Jaguar replaces the AMX-10 RC as part of France''s SCORPION programme, networked with other vehicles to share targets in real time.', ''),
  ('Sd.Kfz. 234/2 Puma', 'Reconnaissance', 'Germany', 'WWII', 'https://upload.wikimedia.org/wikipedia/commons/3/32/Sd.Kfz_234-2_front-diagonal_view.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled', '85 km/h', '900 km', '4', '11.7 tons', '50mm KwK 39/1 gun, 7.92mm MG 42', 'The Puma was an eight-wheeled armoured car with an exceptional range for WWII and a 50mm gun that let it fight its way out of trouble.', ''),
  ('M8 Greyhound', 'Reconnaissance', 'USA', 'WWII', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/93/M8_Greyhound_U.S._Army_Armor_%26_Cavalry_Collection_2023.jpg/960px-M8_Greyhound_U.S._Army_Armor_%26_Cavalry_Collection_2023.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '90 km/h', '560 km', '4', '7.8 tons', '37mm M6 gun, 12.7mm M2, 7.62mm M1919', 'The M8 Greyhound was a fast six-wheeled armoured car used by US cavalry reconnaissance units in Europe and the Pacific.', ''),
  ('Flakpanzer Gepard', 'Air Defense', 'West Germany', 'Cold War', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2a/010_FZD_030.jpg/960px-010_FZD_030.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '65 km/h', '550 km', '3', '47.5 tons', '2x 35mm Oerlikon KDA autocannons', 'The Gepard uses twin radar-guided 35mm guns on a Leopard 1 hull, and it has recently proved effective against drones and cruise missiles.', ''),
  ('ZSU-23-4 Shilka', 'Air Defense', 'Soviet Union', 'Cold War', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7d/%D0%97%D0%A1%D0%A3-23-4_%C2%AB%D0%A8%D0%B8%D0%BB%D0%BA%D0%B0%C2%BB_%D0%B2_%D0%9C%D1%83%D0%B7%D0%B5%D0%B5_%D0%BE%D1%82%D0%B5%D1%87%D0%B5%D1%81%D1%82%D0%B2%D0%B5%D0%BD%D0%BD%D0%BE%D0%B9_%D0%B2%D0%BE%D0%B5%D0%BD%D0%BD%D0%BE%D0%B9_%D0%B8%D1%81%D1%82%D0%BE%D1%80%D0%B8%D0%B8.jpg/960px-%D0%97%D0%A1%D0%A3-23-4_%C2%AB%D0%A8%D0%B8%D0%BB%D0%BA%D0%B0%C2%BB_%D0%B2_%D0%9C%D1%83%D0%B7%D0%B5%D0%B5_%D0%BE%D1%82%D0%B5%D1%87%D0%B5%D1%81%D1%82%D0%B2%D0%B5%D0%BD%D0%BD%D0%BE%D0%B9_%D0%B2%D0%BE%D0%B5%D0%BD%D0%BD%D0%BE%D0%B9_%D0%B8%D1%81%D1%82%D0%BE%D1%80%D0%B8%D0%B8.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '50 km/h', '450 km', '4', '19 tons', '4x 23mm 2A7 autocannons', 'The Shilka pairs four radar-guided 23mm cannons, and it was feared by low-flying aircraft in Vietnam and the Middle East.', ''),
  ('2K22 Tunguska', 'Air Defense', 'Soviet Union', 'Cold War', 'https://upload.wikimedia.org/wikipedia/commons/1/1c/2008_Moscow_Victory_Day_Parade_-_9K22_Tunguska.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled', '65 km/h', '500 km', '4', '34 tons', '2x 30mm 2A38M autocannons, 8x 9M311 SAM', 'The Tunguska combines guns and missiles on one tracked chassis to protect armoured columns from helicopters and aircraft.', ''),
  ('Pantsir-S1', 'Air Defense', 'Russia', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cf/MAKS_Airshow_2013_%28Ramenskoye_Airport%2C_Russia%29_%28521-05%29.jpg/960px-MAKS_Airshow_2013_%28Ramenskoye_Airport%2C_Russia%29_%28521-05%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '90 km/h', '500 km', '3', '30 tons', '2x 30mm 2A38M autocannons, 12x 57E6 SAM', 'The Pantsir-S1 is a truck-mounted gun-missile system that provides short-range defence against aircraft, drones, and precision munitions.', ''),
  ('9K330 Tor', 'Air Defense', 'Soviet Union', 'Cold War', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e4/Tor-M1_SAM_%282%29.jpg/960px-Tor-M1_SAM_%282%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '65 km/h', '500 km', '3', '34 tons', '8x 9M330 surface-to-air missiles', 'The Tor is an all-weather, short-range missile system that can detect and engage several targets while on the move.', ''),
  ('AN/TWQ-1 Avenger', 'Air Defense', 'USA', 'Cold War', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c9/Avenger_missile.jpg/960px-Avenger_missile.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '89 km/h', '443 km', '2', '3.9 tons', '8x FIM-92 Stinger missiles, 12.7mm M3P', 'The Avenger mounts a turret with eight Stinger missiles on a Humvee to protect troops from low-flying aircraft and drones.', ''),
  ('Stryker M-SHORAD', 'Air Defense', 'USA', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/70/M-SHORAD_Stryker.jpg/960px-M-SHORAD_Stryker.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', '97 km/h', '483 km', '4', '20 tons', '30mm XM914 cannon, Stinger and Hellfire missiles, 7.62mm MG', 'M-SHORAD restores short-range air defence to US armoured units, mounting a gun and missile turret on the Stryker chassis.', ''),
  ('Flakpanzer IV Wirbelwind', 'Air Defense', 'Germany', 'WWII', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/61/Wirbelwind_CFB_Borden_4.jpg/960px-Wirbelwind_CFB_Borden_4.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', '38 km/h', '200 km', '5', '22 tons', '4x 20mm Flak 38 autocannons', 'The Wirbelwind ("Whirlwind") put a quad 20mm flak turret on a Panzer IV chassis to protect armoured units from Allied fighter-bombers.', ''),
  ('M16 MGMC', 'Air Defense', 'USA', 'WWII', 'https://upload.wikimedia.org/wikipedia/commons/f/fd/A_M16_MGMC.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled', '72 km/h', '280 km', '5', '9 tons', '4x 12.7mm M2 (Maxson M45 quadmount)', 'The M16 half-track carried four .50-calibre machine guns and was nicknamed the "meat chopper" for its devastating ground-attack use.', ''),
  ('Willys MB Jeep', 'Utility Vehicle', 'USA', 'WWII', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/53/Covered_Willy%27s_jeep_Wings_Over_Wine_Country_2007.JPG/960px-Covered_Willy%27s_jeep_Wings_Over_Wine_Country_2007.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '105 km/h', '480 km', '1–4', '1 ton', '7.62mm M1919 on pintle mount (optional)', 'The Willys MB Jeep became a WWII icon. It could carry troops, tow guns, or serve as an ambulance, and it went on to inspire civilian 4x4s.', ''),
  ('Volkswagen Kübelwagen', 'Utility Vehicle', 'Germany', 'WWII', 'https://upload.wikimedia.org/wikipedia/commons/f/f3/VW_Kuebelwagen_1.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled', '80 km/h', '450 km', '1–4', '0.73 tons', '7.92mm MG 34 (optional)', 'The Kübelwagen was a light, air-cooled military car based on the Volkswagen Beetle; its flat underside let it slide over mud and sand.', ''),
  ('HMMWV (Humvee)', 'Utility Vehicle', 'USA', 'Cold War', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/74/2015_MCAS_Beaufort_Air_Show_041215-M-CG676-161.jpg/960px-2015_MCAS_Beaufort_Air_Show_041215-M-CG676-161.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '113 km/h', '480 km', '1–4', '2.4 tons', '12.7mm M2, 40mm Mk19 or 7.62mm M240 (variant dependent)', 'The Humvee replaced the Jeep as the US military''s light utility vehicle in the 1980s and has been built in dozens of configurations.', ''),
  ('Oshkosh JLTV', 'Utility Vehicle', 'USA', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/63/L-ATV_4.jpg/960px-L-ATV_4.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '113 km/h', '480 km', '2–4', '6.4 tons', '12.7mm M2, 40mm Mk19 or 7.62mm M240 (CROWS)', 'The Joint Light Tactical Vehicle is replacing the Humvee, offering MRAP-level blast protection with far better off-road mobility.', ''),
  ('GAZ Tigr', 'Utility Vehicle', 'Russia', 'Modern', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c1/Zajedni%C4%8Dka_ve%C5%BEba_72_brSO_VS_i_2_br_Specnaz_OSRF_-_GAZ_Tigr_-_05.jpg/960px-Zajedni%C4%8Dka_ve%C5%BEba_72_brSO_VS_i_2_br_Specnaz_OSRF_-_GAZ_Tigr_-_05.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', '140 km/h', '1,000 km', '2 + 9 passengers', '7.2 tons', '7.62mm PKP or 12.7mm Kord (variant dependent)', 'The GAZ Tigr is a Russian high-mobility armoured utility vehicle widely used by the army, police, and special forces.', '');
